CREATE DATABASE IF NOT EXISTS healthcare_ops;
USE healthcare_ops;
CREATE TABLE departments (department_id VARCHAR(10) PRIMARY KEY, department_name VARCHAR(80) NOT NULL, service_line VARCHAR(50) NOT NULL, active_flag CHAR(1) NOT NULL);
CREATE TABLE patients (patient_id VARCHAR(10) PRIMARY KEY, age_band VARCHAR(10), administrative_sex VARCHAR(10), insurance_plan VARCHAR(40), home_region VARCHAR(20), active_flag CHAR(1));
CREATE TABLE doctors (doctor_id VARCHAR(10) PRIMARY KEY, department_id VARCHAR(10) NOT NULL, specialty VARCHAR(60), employment_type VARCHAR(20), start_date DATE, active_flag CHAR(1), FOREIGN KEY (department_id) REFERENCES departments(department_id));
CREATE TABLE appointments (appointment_id VARCHAR(10) PRIMARY KEY, patient_id VARCHAR(10) NOT NULL, doctor_id VARCHAR(10) NOT NULL, department_id VARCHAR(10) NOT NULL, appointment_date DATE NOT NULL, scheduled_start DATETIME, appointment_status VARCHAR(20) NOT NULL, visit_type VARCHAR(30), booking_channel VARCHAR(20), duration_minutes SMALLINT, check_in_time DATETIME NULL, check_out_time DATETIME NULL, wait_minutes SMALLINT NULL, created_date DATE, INDEX ix_appt_date (appointment_date), INDEX ix_appt_dept (department_id), FOREIGN KEY (patient_id) REFERENCES patients(patient_id), FOREIGN KEY (doctor_id) REFERENCES doctors(doctor_id), FOREIGN KEY (department_id) REFERENCES departments(department_id));
CREATE TABLE billing (bill_id VARCHAR(10) PRIMARY KEY, appointment_id VARCHAR(10) NOT NULL UNIQUE, patient_id VARCHAR(10) NOT NULL, charge_amount DECIMAL(10,2) NOT NULL, discount_amount DECIMAL(10,2), adjustment_amount DECIMAL(10,2), net_amount DECIMAL(10,2) NOT NULL, billing_status VARCHAR(20), claim_status VARCHAR(20), bill_date DATE, FOREIGN KEY (appointment_id) REFERENCES appointments(appointment_id), FOREIGN KEY (patient_id) REFERENCES patients(patient_id));
CREATE TABLE payments (payment_id VARCHAR(10) PRIMARY KEY, bill_id VARCHAR(10) NOT NULL, payment_date DATE, payment_amount DECIMAL(10,2) NOT NULL, payment_method VARCHAR(30), payment_status VARCHAR(20), reference_code VARCHAR(20), INDEX ix_payment_date (payment_date), FOREIGN KEY (bill_id) REFERENCES billing(bill_id));
